/// The clip limiter (spec §11 AU-20): a lookahead true-peak limiter, the last
/// stage of `AudioDSPChain`, after an enclosing nest's fold and before the
/// fader. A port of road map "audio" AP0's spike S1 (`OwnLimiter2.swift` at
/// 64 taps, β 10, with Annex 2, taps outermost), which met S1's rule: no
/// allocation or lock on the tap's thread, the same bytes twice and at any
/// buffer size, within 0.1 dB of its ceiling, one constant latency.
///
/// **The detector** reads, per sample and over every channel, the largest of
/// |x|, the three fractional phases of a 64-tap Kaiser-windowed sinc (β 10)
/// 4× interpolator, and BS.1770-4 Annex 2's four 12-tap phases. Both are
/// needed (S1): a detector of Annex 2's size alone lets a broadband onset
/// through by up to +0.97 dB, and Annex 2 over-reads speech by 0.14 dB, so a
/// limiter exact by an accurate meter alone reads −0.86 dBTP on the app's own
/// meter (`Loudness.swift`). Each FIR loops its taps OUTERMOST over
/// element-wise arithmetic, never `vDSP_conv` or `vDSP_biquad`: those give
/// different bits for different buffer sizes, and the player's and the
/// reader's buffers differ (S1).
///
/// **The gain** is the need `min(1, ceiling / peak)`, held by a sliding
/// minimum over `hold` (159) samples, released by a one-pole that never rises
/// above the held value and snaps to it within 2⁻²⁰, then smoothed by the mean
/// of the last `lookahead` (96) released values, summed afresh each sample in
/// one order — no running sum, so a released stage's gain is exactly 1 and the
/// stage is an exact delay. One gain for every channel, so the image does not
/// move. The audio is delayed `latency` (158) samples at any rate: every sample
/// in a peak's interpolation support is gained by no more than that peak
/// needs.
///
/// **What it is told** is the ceiling BEFORE the fader (AU-22): the fader is
/// downstream of the tap, so `AudioLimiterSettings.ceiling` is the clip's
/// dBTP ceiling over its base volume. Nil settings are a ceiling of +∞: the
/// stage keeps its history and its delay, and once released it is a pure
/// delay, which is what a track whose other clips have no limiter needs.
///
/// Real-time rules as `AudioDSP.swift`'s head: every buffer is allocated in
/// `init`, nothing locks, `reset()` restores the fresh state.
final class AudioLimiterStage {
    /// Lookahead samples: S1's 2 ms at 48 kHz, held at 96 at every rate so
    /// the latency is one number (AU-23's lead is in ticks at 48 kHz, as
    /// SY-25's is).
    static let lookahead = 96
    /// The Kaiser interpolator's length.
    static let taps = 64
    /// `lookahead + taps − 2`: what the stage delays its audio by.
    static let latency = 158
    /// `lookahead + taps − 1`: the sliding minimum's window.
    static let hold = 159
    /// The interpolator's Kaiser β.
    static let beta = 10.0
    /// Where the release stops creeping and lands on the held value.
    static let snap = 1.0 / 1_048_576
    /// The release a stage with no settings recovers at.
    static let idleReleaseSeconds = 0.1

    /// BS.1770-4 Annex 2's four phases, as `Loudness.swift` reads them.
    static let annex2: [[Float]] = [
        [0.0017089843750, 0.0109863281250, -0.0196533203125, 0.0332031250000, -0.0594482421875,
         0.1373291015625, 0.9721679687500, -0.1022949218750, 0.0476074218750, -0.0266113281250,
         0.0148925781250, -0.0083007812500],
        [-0.0291748046875, 0.0292968750000, -0.0517578125000, 0.0891113281250, -0.1665039062500,
         0.4650878906250, 0.7797851562500, -0.2003173828125, 0.1015625000000, -0.0582275390625,
         0.0330810546875, -0.0189208984375],
        [-0.0189208984375, 0.0330810546875, -0.0582275390625, 0.1015625000000, -0.2003173828125,
         0.7797851562500, 0.4650878906250, -0.1665039062500, 0.0891113281250, -0.0517578125000,
         0.0292968750000, -0.0291748046875],
        [-0.0083007812500, 0.0148925781250, -0.0266113281250, 0.0476074218750, -0.1022949218750,
         0.9721679687500, 0.1373291015625, -0.0594482421875, 0.0332031250000, -0.0196533203125,
         0.0109863281250, 0.0017089843750],
    ]

    private let channelCount: Int
    private let sampleRate: Double
    private let cap: Int
    private let half = AudioLimiterStage.taps / 2
    /// 3 × taps: the Kaiser interpolator's fractional phases, row p for the
    /// point m + (p + 1)/4.
    private let fir: UnsafeMutablePointer<Float>
    /// 4 × 12: Annex 2's phases, each row reversed.
    private let annex: UnsafeMutablePointer<Float>
    /// Per channel, the last `taps − 1` inputs then the block being read.
    private let history: UnsafeMutablePointer<Float>
    private let scratch: UnsafeMutablePointer<Float>
    /// One tap's products, before they are added into `scratch`.
    private let product: UnsafeMutablePointer<Float>
    private let peaks: UnsafeMutablePointer<Float>
    /// Per channel, a ring of `mask + 1` samples: the delay line.
    private let line: UnsafeMutablePointer<Float>
    private let mask: Int
    private var linePosition = 0
    /// The sliding minimum's monotone deque: values and their sample index.
    private let dequeValues: UnsafeMutablePointer<Float>
    private let dequeIndices: UnsafeMutablePointer<Int>
    private let dequeCapacity = AudioLimiterStage.hold + 2
    private var dequeHead = 0
    private var dequeCount = 0
    /// The last `lookahead` released values.
    private let box: UnsafeMutablePointer<Float>
    private var boxPosition = 0
    /// In Double: a Float one-pole stalls near 1, where a long release's
    /// step falls under half an ulp well before the snap.
    private var envelope: Double = 1
    private var sampleIndex = 0

    init(channelCount: Int, sampleRate: Double, maxFrames: Int) {
        let taps = Self.taps
        self.channelCount = max(0, channelCount)
        self.sampleRate = sampleRate >= 1 ? sampleRate : 48_000
        cap = max(1, maxFrames)
        // Tap k multiplies x[m + k − H + 1] for the point m + p/4.
        fir = .allocate(capacity: 3 * taps)
        let edge = Double(half) + 0.5
        for p in 1...3 {
            var row = [Double](repeating: 0, count: taps)
            for k in 0..<taps {
                let t = Double(p) / 4 - Double(k - half + 1)
                let sinc = t == 0 ? 1 : sin(Double.pi * t) / (Double.pi * t)
                let r = max(0, 1 - (t / edge) * (t / edge))
                row[k] = sinc * Self.besselI0(Self.beta * r.squareRoot()) / Self.besselI0(Self.beta)
            }
            let sum = row.reduce(0, +)
            for k in 0..<taps { fir[(p - 1) * taps + k] = Float(row[k] / sum) }
        }
        annex = .allocate(capacity: 48)
        for phase in 0..<4 {
            for k in 0..<12 { annex[phase * 12 + k] = Self.annex2[phase][11 - k] }
        }
        let stride = taps - 1 + cap
    private let reducers: [AudioNoiseReductionStage]?
    /// Nil when no clip on this track has a limiter — no added latency.
    private let limiter: AudioLimiterStage?
    /// The EQ and hum notch (AU-30): no latency, so always built; nil
    /// settings touch no sample.
    private let eq: AudioEQStage
    /// The gate and the de-esser (AU-47): no latency, so always built; nil
    /// settings reset them and touch no sample. The leveller between them
    /// holds no state (AU-66): `process` is handed its run.
    private let gate: AudioGateStage
    private let deEsser: AudioDeEsserStage

    /// `usesNoiseReduction` and `usesLimiter` are decided for the WHOLE track
    /// when the composition is built, not per buffer: each stage adds a fixed
    /// delay, and switching one in and out at a cut would make the track jump
    /// backwards and forwards (SY-25, AU-23).
    init(
        channelCount: Int, sampleRate: Double, maxFrames: Int, usesNoiseReduction: Bool,
        usesLimiter: Bool = false
    ) {
        self.channelCount = max(0, channelCount)
        compressor = AudioCompressorStage(sampleRate: sampleRate, maxFrames: maxFrames)
        eq = AudioEQStage(channelCount: self.channelCount, sampleRate: sampleRate)
        gate = AudioGateStage(sampleRate: sampleRate, maxFrames: maxFrames)
        deEsser = AudioDeEsserStage(
            channelCount: self.channelCount, sampleRate: sampleRate, maxFrames: maxFrames)
        limiter = usesLimiter && self.channelCount > 0
            ? AudioLimiterStage(
                channelCount: self.channelCount, sampleRate: sampleRate, maxFrames: maxFrames)
            : nil
        if usesNoiseReduction, self.channelCount > 0 {
            // All channels or none: a track whose left channel was filtered
            // and whose right was not would be delayed on one side, which is
            // worse than not filtering at all. `vDSP_create_fftsetup` is the
            // only thing that can fail here, and if it does the clip plays
            // and exports with its pan and compressor and without its noise
            // reduction, rather than not playing.
            let stages = (0..<self.channelCount).compactMap { _ in AudioNoiseReductionStage() }
            reducers = stages.count == self.channelCount ? stages : nil
        } else {
            reducers = nil
        }
    }

    @available(*, unavailable) required init?(coder: NSCoder) {
        fatalError("AudioDSPChain does not support NSCoder")
    }

    /// Drops every bit of carried state — the compressor's envelope, the
    /// reducers' delay lines and noise estimates. `AudioTap` calls this when
    /// the stream restarts, so a seek does not play the previous position's
    /// tail.
    func reset() {
        compressor.reset()
        eq.reset()
        gate.reset()
        deEsser.reset()
        reducers?.forEach { $0.reset() }
        limiter?.reset()
    }

    /// Runs the chain in place over one buffer.
    ///
    /// `params` is the clip under this buffer's timestamp. It changes at every
    /// cut on the track; the stages carry their state across the change, which
    /// is what a track insert does.
    ///
    /// `head` is the clip the HEAD stages (the pick, the EQ and hum) read, nil
    /// for `params`: on a noise-reduced track they see samples the reducer's
    /// lead ahead of the stages after it, so `AudioTap` looks their clip up
    /// there (AU-34). `leveller` is `params.leveller`'s run at this buffer's
    /// lookup frame (AU-66), nil for none.
    func process(
        _ channels: UnsafeMutableBufferPointer<UnsafeMutablePointer<Float>?>, frames: Int,
        params: AudioClipDSP, head: AudioClipDSP? = nil,
        panRamp: AudioPanRamp? = nil, leveller: AudioLevellerRun? = nil
    ) {
        let count = min(channels.count, channelCount)
        guard frames > 0, count > 0 else { return }
        let head = head ?? params

        // The head (AU-34): which channels play, then the EQ and hum. A
        // one-channel track ignores the pick, as it ignores pan.
        if head.channels != .both, count >= 2 {
            pick(channels, count: count, frames: frames, choice: head.channels)
        }
        eq.process(channels, count: count, frames: frames, settings: head.eq)

        if let reducers = reducers {
            for channel in 0..<min(count, reducers.count) {
                guard let data = channels[channel] else { continue }
                reducers[channel].process(data, frames: frames, amount: params.noiseReduction)
            }
        }

        // The gate, the leveller, then the de-esser, on the clip the
        // compressor reads (AU-47, AU-66).
        gate.process(channels, count: count, frames: frames, settings: params.gate)
        leveller?.apply(channels, count: count, frames: frames)
        deEsser.process(channels, count: count, frames: frames, settings: params.deEsser)

        compressor.process(channels, count: count, frames: frames, settings: params.compressor)

        // The head of the Mix stage. The branch is not entered at all for a
        // clip that does not ask for mono — not multiplied by one, not folded
        // with a weight of zero — which is what makes an untouched track's
        // samples bit-identical to the build before this landed, by
        // construction rather than by argument.
        if params.mono, count >= 2 { fold(channels, count: count, frames: frames) }

        // An automated pan moves per sample (AU-87, `AudioAutomation.swift`).
        if let panRamp, count >= 2 {
            panRamp.apply(channels, frames: frames)
        } else { pan(channels, count: count, frames: frames, position: params.pan) }

        // The tail: the fold a nest clip ABOVE this one asked for, after
        // everything this clip does to its own channels, which is what makes
        // the sum of the folded contributors the fold of the sum.
        if params.enclosingMono, count >= 2 { fold(channels, count: count, frames: frames) }

        // The tracks' balance (AU-104), after the folds and before the limiter,
        // so a limited clip hard-panned by its track holds its ceiling. Not
        // entered at unity, and a one-channel track has nothing to lean.
        if params.trackBalance != .unity, count >= 2 {
            balance(channels, frames: frames, by: params.trackBalance)
        }

        // Last, for the whole track once any clip on it asks (AU-23): a
        // clip without a limiter passes through it as a delay.
        limiter?.process(channels, count: count, frames: frames, settings: params.limiter)
    }

    /// The channel pick, in place (AU-34): `left` copies channel 0 into every
    /// channel, `right` channel 1, `swapped` exchanges 0 and 1. Copies and a
    /// scalar swap over raw pointers: nothing allocated.
    private func pick(
        _ channels: UnsafeMutableBufferPointer<UnsafeMutablePointer<Float>?>, count: Int,
        frames: Int, choice: AudioChannelChoice
    ) {
        guard let left = channels[0], let right = channels[1] else { return }
        switch choice {
        case .both:
            return
        case .left, .right:
            let source = choice == .left ? left : right
            for channel in 0..<count {
                guard let data = channels[channel], data != source else { continue }
                data.update(from: source, count: frames)
            }
        case .swapped:
            for i in 0..<frames {
                let held = left[i]
                left[i] = right[i]
                right[i] = held
            }
        }
    }

    /// The pan, in place. Its own method only so the tail fold above it is
    /// reachable: every early return here used to end `process`.
    ///
    /// Pan needs somewhere to pan TO. A mono composition track is prepared
    /// with one channel and is widened to stereo downstream of the tap, so
    /// there is nothing here to lean; the pan is silently inaudible on such a
    /// clip rather than turning into a volume change, which is what applying
    /// half a pan law to a single channel would be.
    private func pan(
        _ channels: UnsafeMutableBufferPointer<UnsafeMutablePointer<Float>?>, count: Int,
        frames: Int, position: Double
    ) {
        guard count >= 2 else { return }
        let gains = AudioPanLaw.gains(position)
        guard gains.left != 1 || gains.right != 1 else { return }
        var left = gains.left
        var right = gains.right
        if let data = channels[0] { vDSP_vsmul(data, 1, &left, data, 1, vDSP_Length(frames)) }
        if let data = channels[1] { vDSP_vsmul(data, 1, &right, data, 1, vDSP_Length(frames)) }
    }

    /// The tracks' balance, in place on channels 0 and 1, as `pan` leans.
    private func balance(
        _ channels: UnsafeMutableBufferPointer<UnsafeMutablePointer<Float>?>, frames: Int,
        by balance: AudioTrackBalance
    ) {
        var left = balance.left
        var right = balance.right
        if let data = channels[0] { vDSP_vsmul(data, 1, &left, data, 1, vDSP_Length(frames)) }
        if let data = channels[1] { vDSP_vsmul(data, 1, &right, data, 1, vDSP_Length(frames)) }
    }

    /// Averages EVERY channel and writes the average to all of them.
    ///
    /// **Every channel, not L and R.** `prepare` is handed the COMPOSITION
    /// track's channel count, so a 5.1 source gives 6; folding only channels 0
    /// and 1 would leave four untouched and produce something that is neither
    /// mono nor the original. At two channels this is exactly (L+R)/2.
    ///
    /// Allocation-free and stateless: `count` linear passes plus `count − 1`
    /// copies over at most `maxFrames` floats, which is two orders of
    /// magnitude under one noise-reduction frame. The accumulator is the first
    /// channel that actually has a buffer, and the divisor counts only the
    /// channels that contributed — a null buffer must not quietly attenuate
    /// the rest.
    private func fold(
        _ channels: UnsafeMutableBufferPointer<UnsafeMutablePointer<Float>?>, count: Int,
        frames: Int
    ) {
        var accumulator: UnsafeMutablePointer<Float>?
        var summed = 0
        for channel in 0..<count {
            guard let data = channels[channel] else { continue }
            summed += 1
            guard let into = accumulator else {
                accumulator = data
                continue
            }
            vDSP_vadd(into, 1, data, 1, into, 1, vDSP_Length(frames))
        }
        guard let into = accumulator, summed >= 2 else { return }
        var scale = 1 / Float(summed)
        vDSP_vsmul(into, 1, &scale, into, 1, vDSP_Length(frames))
        for channel in 0..<count {
            guard let data = channels[channel], data != into else { continue }
            data.update(from: into, count: frames)
        }
    }
}

