    struct MeasurementPlan {
        let plan: CompositionPlan
        /// The edited plan as JSON, keys sorted: the builder's `planJSON` and
        /// the memo key's `plan`.
        let json: String
        /// The span of the clip's segments, timeline ticks.
        let start: Ticks
        let end: Ticks
    }

