    static func dsp(
        _ audio: AudioProps, volume: Double, level: Double?,
        leveller: [Ticks: AudioLevellerCurve]?, enclosingMono: Bool
    ) -> AudioClipDSP {
        AudioClipDSP(
            pan: audio.pan,
            compressor: audio.compressor.map {
                AudioCompressorSettings(
                    thresholdDB: $0.thresholdDb, ratio: $0.ratio,
                    attackSeconds: seconds($0.attack), releaseSeconds: seconds($0.release),
                    makeupDB: $0.makeupDb)
